```js
import { test, expect } from '@playwright/test';

/** Hold back all client JS until the test releases it */
async function hold_js(page) {
	const held = [];
	let released = false;
	await page.route(/\.js(\?.*)?$/, (route) => {
		if (released) return route.continue();
		held.push(() => route.continue());
	});
	return async () => {
		expect(held.length).toBeGreaterThan(0); // JS really was held back
		released = true;
		await Promise.all(held.map((fn) => fn()));
		await page.locator('body[data-hydrated]').waitFor({ state: 'attached' });
	};
}

for (const route of ['/bind', '/oneway', '/selected']) {
	test(`<select> ${route}: selection made before hydration survives hydration`, async ({ page }) => {
		const hydrate = await hold_js(page);
		await page.goto(route, { waitUntil: 'domcontentloaded' });

		const select = page.locator('select');
		await select.selectOption('b'); // user picks "b" before hydration
		await expect(page.locator('body[data-hydrated]')).toHaveCount(0); // not hydrated yet

		await hydrate();

		await expect(select).toHaveValue('b');
	});
}
```

