for (const k of ["document", "Node", "Element", "HTMLElement", "Comment", "Text", "DocumentFragment", "navigator", "getComputedStyle", "MutationObserver"]) globalThis[k] ??= dom.window[k];
const { hydrate, mount } = await import("svelte");
const App = (await import("./client/App.js")).default;
hydrate(App, { target: document.getElementById("h") });
mount(App, { target: document.getElementById("m") });
for (const id of ["h", "m"]) console.log(id, document.querySelector(`#${id} p`).__svelte_meta?.loc ?? "MISSING");
