body_text:
When using a fractional exponent such as `Rational(a, b)`, if this gets compared against the same expression to the same power but expressed in floating point numbers, sometimes `.simplify()` will not take both expressions as being equal.

For example, compare these two:

```python
from sympy import *

class Phi(Function):
    def fdiff(self, x):
        return phi(self.args[0])

class phi(Function):
    def fdiff(self, x):
        return -self.args[0]*phi(self.args[0])

x, k, d, s, r = symbols("x k d \\sigma \\rho")


fn = -log( Phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2)) )
target_expr = diff(diff(fn, s), r)

expr_w_numbers = (
    x*sqrt(1 - tanh(r)**2) * phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2)) * exp(-s) / (
        Phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2))
    )

    -x*(k + x*tanh(r)/exp(s)) * (
        x*sqrt(1 - tanh(r)**2)*exp(-s) + (2-2*tanh(r)**2)*(k + x*tanh(r)/exp(s)) * tanh(r) / (2 * (1 - tanh(r)**2)**1.5)
    ) * phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2)) * exp(-s) * tanh(r) / (
        (1 - tanh(r)**2) * Phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2))
    )

    -x * (
        x*sqrt(1 - tanh(r)**2)*exp(-s)
        + (2-2*tanh(r)**2) * (k + x*tanh(r)/exp(s)) * tanh(r) / (2 * (1 - tanh(r)**2)**1.5)
    ) * phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2))**2 *exp(-s)*tanh(r) / (
        sqrt(1 - tanh(r)**2) * Phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2))**2
    )

    +x*(2 - 2*tanh(r)**2) * phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2)) * exp(-s) * tanh(r)**2 / (
        2 * (1 - tanh(r)**2)**1.5 * Phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2))
    )
)

expr_w_fractions = (
    x*sqrt(1 - tanh(r)**2) * phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2)) * exp(-s) / (
        Phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2))
    )

    -x*(k + x*tanh(r)/exp(s)) * (
        x*sqrt(1 - tanh(r)**2)*exp(-s) + (2-2*tanh(r)**2)*(k + x*tanh(r)/exp(s)) * tanh(r) / (2 * (1 - tanh(r)**2)**Rational(3/2))
    ) * phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2)) * exp(-s) * tanh(r) / (
        (1 - tanh(r)**2) * Phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2))
    )

    -x * (
        x*sqrt(1 - tanh(r)**2)*exp(-s)
        + (2-2*tanh(r)**2) * (k + x*tanh(r)/exp(s)) * tanh(r) / (2 * (1 - tanh(r)**2)**Rational(3/2))
    ) * phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2))**2 *exp(-s)*tanh(r) / (
        sqrt(1 - tanh(r)**2) * Phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2))**2
    )

    +x*(2 - 2*tanh(r)**2) * phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2)) * exp(-s) * tanh(r)**2 / (
        2 * (1 - tanh(r)**2)**Rational(3/2) * Phi((k + x*tanh(r)/exp(s)) / sqrt(1 - tanh(r)**2))
    )
)
```

```pyton
#############
(target_expr - expr_w_fractions).simplify() # simplifies to zero
(target_expr - expr_w_numbers).simplify() # simplifies to a non-zero expression
```

