body_text:
## Summary

I observe a very large performance gap between Burn CUDA and PyTorch CUDA on an equivalent **minimal synthetic training loop**:

- Burn median step: **1239.90 ms**
- PyTorch median step: **33.97 ms**
- Burn is about **36.5x slower**

This reproduces with:
- no dataset / dataloader
- fixed zero input tensor
- simple loss
- train loop only (`forward -> loss -> backward -> optimizer.step`)

## Environment
- GPU: NVIDIA Quadro RTX 6000
- Driver: 580.126.09
- NVIDIA-SMI CUDA Version: 13.0
- nvcc --version: 12.6 (V12.6.85)
- rustc --version: rustc 1.93.0 (254b59607 2026-01-19)
- Burn crate: 0.20.0
- yolox-burn: https://github.com/tracel-ai/models (Cargo resolved rev 4bca43f3)
- yolox-pytorch : https://github.com/Megvii-BaseDetection/YOLOX
---

## Minimal repros 

### 1) Burn CUDA minimal repro

```rust
#![recursion_limit = "256"]

use burn::backend::cuda::CudaDevice;
use burn::backend::{Autodiff, Cuda};
use burn::optim::{AdamConfig, GradientsParams, Optimizer};
use burn::tensor::backend::Backend;
use burn::tensor::Tensor;
use yolox_burn::model::yolox::Yolox;

type B = Autodiff<Cuda>;

const BATCH_SIZE: usize = 4;
const IMAGE_SIZE: usize = 416;
const STEPS: usize = 20;
const LR: f64 = 1e-4;
const NUM_CLASSES: usize = 1;

fn main() {
    let device = CudaDevice::default();
    let mut model = Yolox::<B>::yolox_nano(NUM_CLASSES, &device);
    let mut optimizer = AdamConfig::new().init();

    let input = Tensor::<B, 4>::zeros([BATCH_SIZE, 3, IMAGE_SIZE, IMAGE_SIZE], &device);

    let mut last_loss = 0.0f32;
    for _ in 0..STEPS {
        let output = model.forward(input.clone());
        let loss = (output.clone() * output).mean();
        let grads = loss.clone().backward();
        let grads = GradientsParams::from_grads(grads, &model);
        model = optimizer.step(LR, model, grads);
        last_loss = loss.detach().into_scalar();
    }

    B::sync(&device).unwrap();
    println!("last_loss={}", last_loss);
}
```
### 2) Pytorch CUDA  minimal repro


```python 

BATCH_SIZE = 4
IMAGE_SIZE = 416
STEPS = 20
LR = 1e-4
NUM_CLASSES = 1
DEVICE = torch.device("cuda:0")

def build_yolox_nano(num_classes):
    backbone = YOLOPAFPN(
        depth=0.33,
        width=0.25,
        in_features=("dark3", "dark4", "dark5"),
        in_channels=[256, 512, 1024],
        depthwise=True,
        act="silu",
    )
    head = YOLOXHead(
        num_classes=num_classes,
        width=0.25,
        strides=[8, 16, 32],
        in_channels=[256, 512, 1024],
        depthwise=True,
        act="silu",
    )
    model = YOLOX(backbone=backbone, head=head)
    model.head.initialize_biases(1e-2)
    return model

def main():
    if not torch.cuda.is_available():
        raise RuntimeError("CUDA not available")

    model = build_yolox_nano(NUM_CLASSES).to(DEVICE)
    model.eval()  # model returns predictions directly in eval mode
    opt = torch.optim.Adam(model.parameters(), lr=LR)
    x = torch.zeros(BATCH_SIZE, 3, IMAGE_SIZE, IMAGE_SIZE, device=DEVICE)

    loss = None
    for _ in range(STEPS):
        opt.zero_grad(set_to_none=True)
        out = model(x)
        loss = (out * out).mean()
        loss.backward()
        opt.step()

    torch.cuda.synchronize(DEVICE)
    print(f"last_loss={float(loss.item())}")

if __name__ == "__main__":
    main()

```

