`src/main.rs`:

```rust
use burn::nn::{Linear, LinearConfig};
use burn::optim::{
    AdamConfig, AdamWConfig, GradientsParams, ModuleOptimizer, SgdConfig,
    momentum::MomentumConfig,
};
use burn::prelude::*;
use burn::tensor::{Distribution, activation::relu};
use std::cell::{Cell, RefCell};

#[derive(Module, Debug)]
struct Mlp {
    l1: Linear,
    l2: Linear,
}

struct Trainer {
    model: Option<Mlp>,
    optim: ModuleOptimizer,
    lr: f64,
    x: Tensor<2>,
    y: Tensor<2>,
}

impl Trainer {
    fn new(opt: &str) -> Self {
        let device = Device::default();
        device.seed(0);
        let ad = device.clone().autodiff();
        let model = Mlp {
            l1: LinearConfig::new(32, 128).init(&ad),
            l2: LinearConfig::new(128, 8).init(&ad),
        };
        let x = Tensor::random([64, 32], Distribution::Normal(0.0, 1.0), &device);
        let y = Tensor::random([64, 8], Distribution::Normal(0.0, 1.0), &device);
        let optim = match opt {
            "sgd" => SgdConfig::new().init(),
            "sgd-mom" => SgdConfig::new().with_momentum(Some(MomentumConfig::new())).init(),
            "adam" => AdamConfig::new().init(),
            "adamw" => AdamWConfig::new().init(),
            other => panic!("OPT: {other}"),
        };
        Self { model: Some(model), optim, lr: 1e-2, x, y }
    }

    /// One training step on the fixed batch; the loss before the update.
    fn step(&mut self) -> Tensor<1> {
        let model = self.model.take().unwrap();
        let pred = model.l2.forward(relu(model.l1.forward(self.x.clone().autodiff())));
        let loss = (pred - self.y.clone().autodiff()).square().mean();
        let grads = GradientsParams::from_grads(loss.backward(), &model);
        self.model = Some(self.optim.step(self.lr, model, grads));
        loss.inner()
    }
}

fn main() {
    let opt = std::env::var("OPT").unwrap_or_else(|_| "sgd".into());
    let decay = std::env::var("DECAY").is_ok_and(|v| v == "1");
    let lr = |i: usize| if decay { 1e-2 * 0.9f64.powi(i as i32) } else { 1e-2 };
    let device = Device::default();
    let n = 6;

    // Graph: 2 eager steps (so the optimizer state exists), capture, replay.
    let trainer = RefCell::new(Trainer::new(&opt));
    for _ in 0..2 {
        trainer.borrow_mut().step();
    }
    let runs = Cell::new(0);
    let step = || {
        runs.set(runs.get() + 1);
        trainer.borrow_mut().step()
    };
    // One eager run first: a cold capture fails otherwise (#5772).
    drop(step());
    let mut graph = burn::tensor::capture(&device, step);
    assert!(graph.is_hardware(), "no hardware graph");
    // Every closure run but the recording was a real step.
    let executed = runs.get() - 1;
    let mut replayed = Vec::new();
    for i in 0..n {
        trainer.borrow_mut().lr = lr(i);
        let loss = unsafe { graph.replay() };
        replayed.push(loss.clone().into_scalar::<f32>());
    }

    // Eager: the same steps.
    let mut trainer = Trainer::new(&opt);
    for _ in 0..2 + executed {
        trainer.step();
    }
    println!("OPT={opt} DECAY={}\nstep  replayed   eager", decay as u8);
    for (i, replayed) in replayed.iter().enumerate() {
        trainer.lr = lr(i);
        let eager = trainer.step().into_scalar::<f32>();
        let mark = if *replayed == eager { "" } else { "  <- differs" };
        println!("{i:>4}  {replayed:.6}  {eager:.6}{mark}");
    }
}
```

